import {classifyMuscle,detailMuscles} from './anatomy-data.js';
import * as T from './vendor/three.module.js';
import {GLTFLoader} from './vendor/GLTFLoader.js';
import {muscleColors} from './catalog.js';
let cached;
const classify=classifyMuscle;
export function createAtlas(container,initial,onSelect){
 const renderer=new T.WebGLRenderer({antialias:true,alpha:true,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.outputColorSpace=T.SRGBColorSpace;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.3;container.appendChild(renderer.domElement);renderer.domElement.setAttribute('aria-label','Gerçek kas anatomisi: döndürmek için sürükle, kas seçmek için dokun.');
 const scene=new T.Scene(),camera=new T.PerspectiveCamera(32,1,.01,50),body=new T.Group();camera.position.set(0,0,7.3);scene.add(body);scene.add(new T.HemisphereLight(0xe8efff,0x252437,2.2));for(const [color,power,pos]of[[0xfff1df,3,[-3,4,5]],[0x9cbeff,2,[4,1,2]],[0x40ffd2,2,[0,3,-3]]]){const l=new T.DirectionalLight(color,power);l.position.set(...pos);scene.add(l);}
 const loading=document.createElement('div');loading.className='atlas-loading';loading.innerHTML='<span class="loader-ring"></span><strong>Anatomi yükleniyor</strong><small>467 anatomik yapı hazırlanıyor…</small>';container.appendChild(loading);
 let heat=null;const heatColor=n=>n>=8?'#ff9b60':n>=4?'#bda2ff':n>0?'#69d8be':'#53596a';
 let alive=true,frame,meshes=[],selected=initial,angle=0,zoom=7.3,last=0,down=null,moved=false;
 function paint(){meshes.forEach(m=>{const k=m.userData.group,color=k?(heat?heatColor(heat[k]||0):(muscleColors[k]||'#e9b9a8')):'#d9c9b3';m.material.color.set(color);m.material.emissive.set((k===selected||detailMuscles[k]?.parent===selected)?color:0);m.material.emissiveIntensity=(k===selected||detailMuscles[k]?.parent===selected)?.18:0;});}
 if(!cached)cached=new GLTFLoader().loadAsync('./assets/anatomy.glb').catch(e=>{cached=null;throw e;});
 cached.then(gltf=>{if(!alive)return;const root=gltf.scene.clone(true);root.rotation.x=-Math.PI/2;root.updateMatrixWorld(true);const box=new T.Box3().setFromObject(root),size=box.getSize(new T.Vector3()),center=box.getCenter(new T.Vector3()),scale=3.75/size.y;root.scale.setScalar(scale);root.position.copy(center.multiplyScalar(-scale));root.traverse(m=>{if(!m.isMesh)return;m.material=new T.MeshStandardMaterial({roughness:.53,metalness:.04,side:T.DoubleSide});m.userData={group:classify(m.name),anatomicalName:m.name.replaceAll('_',' ')};meshes.push(m);});body.add(root);paint();loading.remove();}).catch(()=>{if(alive)loading.innerHTML='<strong>Model yüklenemedi</strong><small>Yenile veya kas düğmelerini kullan.</small>';});
 const ray=new T.Raycaster(),pointer=new T.Vector2();function resize(){renderer.setSize(container.clientWidth,container.clientHeight);camera.aspect=container.clientWidth/container.clientHeight;camera.updateProjectionMatrix();}const observer=new ResizeObserver(resize);observer.observe(container);resize();
 function start(e){down={x:e.clientX,y:e.clientY,angle};moved=false;}function move(e){if(!down)return;if(Math.abs(e.clientX-down.x)>6){moved=true;angle=down.angle+(e.clientX-down.x)*.012;}if(Math.abs(e.clientY-down.y)>15)moved=true;}function end(e){if(!down)return;down=null;if(moved)return;const r=renderer.domElement.getBoundingClientRect();pointer.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(pointer,camera);const hit=ray.intersectObjects(meshes,false)[0];if(hit?.object.userData.group){selected=hit.object.userData.group;paint();onSelect(selected);}}
 const cancel=()=>{down=null;};renderer.domElement.addEventListener('pointerdown',start);window.addEventListener('pointermove',move);window.addEventListener('pointerup',end);window.addEventListener('pointercancel',cancel);
 function animate(t){if(!alive)return;frame=requestAnimationFrame(animate);if(t-last<33||document.hidden)return;last=t;body.rotation.y+=(angle-body.rotation.y)*.14;camera.position.z+=(zoom-camera.position.z)*.13;renderer.render(scene,camera);}frame=requestAnimationFrame(animate);
 return{setHeat:counts=>{heat=counts;paint();},select:k=>{selected=k;paint();},rotate:r=>{angle=r;},zoom:d=>{zoom=T.MathUtils.clamp(zoom-d*.6,4.3,9);},dispose:()=>{alive=false;cancelAnimationFrame(frame);observer.disconnect();renderer.domElement.removeEventListener('pointerdown',start);window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',end);window.removeEventListener('pointercancel',cancel);meshes.forEach(m=>m.material.dispose());renderer.dispose();renderer.domElement.remove();loading.remove();}};
}
